int insideCount = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction for the ray
    double theta = 2.0 * M_PI * (static_cast<double>(std::rand()) / std::RAND_MAX);
    double phi = std::acos(1.0 - 2.0 * (static_cast<double>(std::rand()) / std::RAND_MAX));

    double dx = std::sin(phi) * std::cos(theta);
    double dy = std::sin(phi) * std::sin(theta);
    double dz = std::cos(phi);

    CGALPoint p_cgal(p.x(), p.y(), p.z());
    CGALPoint dir_cgal(dx, dy, dz);

    // A ray is defined by a point and a direction. 
    // In CGAL AABB_tree, we can use a segment from p to a point very far away 
    // or use the numberIntersectedPrimitives with a ray-like segment.
    // Since numberIntersectedPrimitives takes two points (p1, p2), we create a far point.
    double farDist = 1e6; // Sufficiently large distance to act as a ray
    Point3d p_far(p.x() + dx * farDist, p.y() + dy * farDist, p.z() + dz * farDist);

    if (numberIntersectedPrimitives(p, p_far) % 2 != 0) {
        insideCount++;
    }
}

// The point is considered inside if the majority of rays indicate it is inside
return insideCount > (numberOfChecks / 2);

